@page "/recipes/{CuisineId:int}"
@using sv_eb4391e1381949adab0a29d92dc659b8.Services
@using Microsoft.AspNetCore.Components.Routing
@rendermode InteractiveServer
@implements IDisposable
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation

<PageTitle>Recipes</PageTitle>

@if (_error is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_error</p>
        <button class="btn btn-outline-danger" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_recipes is null)
{
    <p><em>Loading recipes…</em></p>
}
else
{
    @if (_isRefreshing)
    {
        <p><em>Refreshing…</em></p>
    }

    <h3>Recipes for Cuisine @CuisineId (@Sort)</h3>

    @if (_displayedRecipes.Count == 0)
    {
        <p>No recipes found for this cuisine.</p>
    }
    else
    {
        <ul>
            @foreach (var recipe in _displayedRecipes)
            {
                <li>
                    <strong>@recipe.Title</strong> — @recipe.Description
                    <br /><small>Prep time: @recipe.PrepTimeMinutes min</small>
                </li>
            }
        </ul>
    }
}

@code {
    [Parameter] public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private List<Recipe> _displayedRecipes = new();
    private bool _isRefreshing;
    private string? _error;

    private int _lastLoadedCuisineId;
    private CancellationTokenSource? _loadCts;

    protected override async Task OnParametersSetAsync()
    {
        // Only reload data when the cuisine changes, not when sort changes
        if (CuisineId != _lastLoadedCuisineId)
        {
            await LoadRecipesAsync();
        }
        else if (_recipes is not null)
        {
            // Sort changed but cuisine didn't — just reorder
            ApplySort();
        }
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight request
        await CancelPendingLoadAsync();

        _error = null;
        _lastLoadedCuisineId = CuisineId;

        // Determine loading state: initial load vs refresh
        if (_recipes is null)
        {
            // First load — the template shows the "Loading recipes…" placeholder
        }
        else
        {
            _isRefreshing = true;
        }

        _loadCts = new CancellationTokenSource();
        var token = _loadCts.Token;
        var cuisineId = CuisineId;

        try
        {
            var results = await RecipeService.GetByCuisineAsync(cuisineId, token);

            // Guard against a late completion after cancellation
            if (token.IsCancellationRequested)
                return;

            _recipes = results;
            ApplySort();
            _error = null;
        }
        catch (OperationCanceledException) when (token.IsCancellationRequested)
        {
            // Expected when we cancel — do nothing
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", cuisineId);
            _error = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", cuisineId);
            _error = "Something went wrong loading recipes. Please try again.";
        }
        finally
        {
            _isRefreshing = false;
        }
    }

    private void ApplySort()
    {
        if (_recipes is null)
            return;

        _displayedRecipes = Sort?.ToLowerInvariant() switch
        {
            "newest" => _recipes.OrderByDescending(r => r.Id).ToList(),
            "popular" => _recipes.OrderBy(r => r.PrepTimeMinutes).ToList(),
            _ => _recipes.ToList(),
        };
    }

    private async Task RetryAsync()
    {
        _error = null;
        _lastLoadedCuisineId = 0; // Force reload
        await LoadRecipesAsync();
    }

    private async Task CancelPendingLoadAsync()
    {
        if (_loadCts is not null)
        {
            await _loadCts.CancelAsync();
            _loadCts.Dispose();
            _loadCts = null;
        }
    }

    public void Dispose()
    {
        _loadCts?.Cancel();
        _loadCts?.Dispose();
        _loadCts = null;
    }
}

